import type * as THREE from 'three';
import { PresentationMinimap } from './PresentationMinimap';

export interface DeveloperDiagnosticsOptions {
  root: HTMLElement;
  renderer: THREE.WebGLRenderer;
  scene: THREE.Scene;
  camera: THREE.Camera;
  now?: () => number;
}

export class DeveloperDiagnostics {
  readonly minimap = new PresentationMinimap();
  readonly overlay = document.createElement('div');
  private frames = 0;
  private start: number;
  private last: number;
  private fps = 0;
  private visible = true;
  private wire = false;
  private readonly now: () => number;

  constructor(private readonly o: DeveloperDiagnosticsOptions) {
    this.now = o.now ?? (() => performance.now());
    this.start = this.last = this.now();
    this.overlay.className = 'dev-diagnostics';
    o.root.append(this.overlay, this.minimap.element);
    window.addEventListener('keydown', this.onKey);
    this.render(0);
  }

  frame() {
    const n = this.now();
    const ms = Math.max(0, n - this.last);
    this.last = n;
    this.frames++;
    const e = n - this.start;
    if (e >= 500) {
      this.fps = (this.frames * 1000) / e;
      this.frames = 0;
      this.start = n;
    }
    if (this.visible) this.render(ms);
  }

  dispose() {
    window.removeEventListener('keydown', this.onKey);
    this.overlay.remove();
    this.minimap.element.remove();
  }

  private render(ms: number) {
    const p = this.o.camera.position;
    const i = this.o.renderer.info.render;
    this.overlay.textContent = [
      `FPS ${this.fps.toFixed(0)} · ${ms.toFixed(1)} ms`,
      `Draw ${i.calls} · Tri ${i.triangles}`,
      `Cam ${p.x.toFixed(1)}, ${p.y.toFixed(1)}, ${p.z.toFixed(1)}`,
      'F1 overlay · F2 wireframe · F3 minimap',
    ].join('\n');
  }

  private readonly onKey = (e: KeyboardEvent) => {
    if (e.code === 'F1') {
      e.preventDefault();
      this.visible = !this.visible;
      this.overlay.hidden = !this.visible;
    } else if (e.code === 'F2') {
      e.preventDefault();
      this.wire = !this.wire;
      this.o.scene.traverse((x) => {
        if (!('material' in x)) return;
        const m = (x as THREE.Mesh).material;
        for (const a of Array.isArray(m) ? m : [m])
          if (a && 'wireframe' in a) (a as THREE.MeshBasicMaterial).wireframe = this.wire;
      });
    } else if (e.code === 'F3') {
      e.preventDefault();
      this.minimap.setVisible(!this.minimap.visible);
    }
  };
}
